# Add /repo to path
REPO_ROOT = "/repo"
if REPO_ROOT not in sys.path:
    sys.path.insert(0, REPO_ROOT)

def _install_module_stub(name: str, *, is_package: bool = False) -> types.ModuleType:
    mod = types.ModuleType(name)
    if is_package:
        mod.__path__ = []
    sys.modules[name] = mod
    return mod

def _install_heavy_dep_stubs() -> None:
    """Mock torch/PIL/etc. PIL must be a package so PIL.PngImagePlugin imports work."""
    for mod in (
        "torch",
        "torchvision",
        "numpy",
        "pandas",
        "transformers",
        "safetensors",
        "safetensors.torch",
    ):
        if mod not in sys.modules:
            sys.modules[mod] = MagicMock()
    if "PIL" not in sys.modules:
        pil = _install_module_stub("PIL", is_package=True)
        for sub in ("Image", "ImageDraw", "ImageFont", "PngImagePlugin", "JpegImagePlugin"):
            submod = _install_module_stub(f"PIL.{sub}")
            setattr(pil, sub, submod)
    if "Pillow" not in sys.modules:
        sys.modules["Pillow"] = sys.modules.get("PIL") or MagicMock()
    # Stub typing_extensions if missing (common dependency)
    if "typing_extensions" not in sys.modules:
        sys.modules["typing_extensions"] = MagicMock()

# Install heavy deps to avoid import errors during module load
_install_heavy_dep_stubs()

def run_test():
    try:
        # Import the target module
        from comfy_extras.nodes_string import RegexExtract
    except ImportError as e:
        # If import fails, check if it's due to missing deps and retry with stubs
        error_msg = str(e)
        if "No module named" in error_msg:
            # Extract module name from error
            parts = error_msg.split("'")
            if len(parts) >= 2:
                missing_mod = parts[1]
                # Install minimal stub for the missing module
                sys.modules[missing_mod] = MagicMock()
                try:
                    from comfy_extras.nodes_string import RegexExtract
                except ImportError as e2:
                    print(f"STATUS: HARNESS_ERROR | {e2}")
                    sys.exit(2)
            else:
                print(f"STATUS: HARNESS_ERROR | {e}")
                sys.exit(2)
        else:
            print(f"STATUS: HARNESS_ERROR | {e}")
            sys.exit(2)

    # Verify the class exists and has the execute method
    if not hasattr(RegexExtract, 'execute'):
        print("STATUS: HARNESS_ERROR | RegexExtract class missing execute method")
        sys.exit(2)

    # Get the execute method signature
    try:
        sig = inspect.signature(RegexExtract.execute)
    except Exception as e:
        print(f"STATUS: HARNESS_ERROR | Failed to inspect signature: {e}")
        sys.exit(2)

    # Create an instance
    try:
        regex_extractor = RegexExtract()
    except Exception as e:
        print(f"STATUS: HARNESS_ERROR | Failed to instantiate RegexExtract: {e}")
        sys.exit(2)

    # Test the execute method with different modes
    # Based on the candidate, we need to test the 'All Groups' mode
    test_cases = [
        # (pattern, string, mode, expected_type)
        (r"(\d+)-(\w+)", "123-abc", "First Match", list),
        (r"(\d+)-(\w+)", "123-abc 456-def", "All Matches", list),
        (r"(\d+)-(\w+)", "123-abc", "First Group", list),
        (r"(\d+)-(\w+)", "123-abc 456-def", "All Groups", list),
    ]

    for pattern, string, mode, expected_type in test_cases:
        try:
            result = regex_extractor.execute(pattern, string, mode)

            # Check if result is a tuple (ComfyUI nodes return tuples)
            if not isinstance(result, tuple):
                print(f"STATUS: CRASHED | execute did not return a tuple for mode={mode}")
                sys.exit(1)

            # Check if the first element of the tuple is the expected type
            if not isinstance(result[0], expected_type):
                print(f"STATUS: MISMATCH | expected {expected_type}, got {type(result[0])} for mode={mode}")
                sys.exit(1)

            # For 'All Groups' mode, verify the result makes sense
            if mode == "All Groups":
                # Should return a list of tuples (each tuple is a group match)
                if len(result[0]) > 0:
                    for group_match in result[0]:
                        if not isinstance(group_match, tuple):
                            print(f"STATUS: MISMATCH | All Groups mode should return list of tuples")
                            sys.exit(1)
        except Exception as e:
            print(f"STATUS: CRASHED | {type(e).__name__}: {e} for mode={mode}")
            sys.exit(1)

    # Test with invalid mode to check for implicit None return
    try:
        result = regex_extractor.execute(r"(\d+)", "123", "Invalid Mode")
        # If we get here without crash, check if result is None (implicit return)
        if result is None or (isinstance(result, tuple) and result[0] is None):
            print("STATUS: CRASHED | Invalid mode returned None (implicit return bug)")
            sys.exit(1)
    except Exception as e:
        # Exception is acceptable for invalid mode
        pass

    print("STATUS: SAFE")
    sys.exit(0)

if __name__ == "__main__":
    run_test()
